#!/usr/bin/env bash
#
# regen-uki.sh - rebuild a slot's UKI in place, from inside that slot.
#
# WHY THIS EXISTS. A change to a dracut module under
# image_profiles/*/overlay/rootfs/usr/lib/dracut/modules.d/ only reaches a UKI
# on the next IMAGE BUILD - the module lives in the image's overlay, and
# `bootstrap`/`configure` regenerate the UKI from the image, not from the
# working tree. That is correct behaviour and it makes a hook fix untestable
# for the length of an image build.
#
# But the UKI is generated by gen-efi inside the slot:
#
#   dracut --force --uefi --kver "$kernel_ver" \
#          --kernel-cmdline "$kernel_cmdline" "${uki_path}.tmp"
#   sign_efi_binary "${uki_path}.tmp"          # sbsign with the MOK keypair
#
# so for TESTING a module change, the module can be written into the slot and
# the UKI regenerated through exactly that path. The cmdline is taken from the
# UKI that is already there rather than regenerated, so the bad UKI differs
# from a good one in nothing but the module.
#
# THIS IS NOT SHIPPING. It writes into a live slot's ESP; the image still
# carries the old module, and an image rebuild is what makes the change real
# for users.
#
# Usage (from `build.sh test enter <slot> --`):
#     regen-uki.sh [--break-root] [--expect-in-initrd=TEXT] <slot> [<slot>]
#
#   --expect-in-initrd=TEXT
#                  assert TEXT is present in the initramfs inside the UKI that was
#                  just produced, and FAIL if it is not. This exists because a
#                  regeneration can take its input from somewhere other than the
#                  working tree and report success: `enter` boots the nspawn
#                  overlay, and a stale copy of the module there shadowed a fix
#                  that had been written into the slot's real subvolume. The only
#                  symptom was an artifact that came out SMALLER than the one it
#                  replaced. lsinitramfs is not usable here - it reports zero
#                  99shanios entries on a UKI that demonstrably has them - so the
#                  check goes to the archive directly: objcopy the .initrd out,
#                  decompress, and look at the cpio listing.
#   --break-root   rebuild the UKI with its root subvol pointed at a subvolume
#                  that does not exist (`subvol=@no-such-slot`), so the candidate
#                  GENUINELY fails to mount its root. That is the difference
#                  between a hook that fires and a recovery that works: the
#                  failing boot cannot act on its own marker, so the whole loop
#                  is only testable if boot 1 really fails.
#                  Built by construction, not by patching a UKI afterwards - a
#                  patched UKI differs from a real one in ways the boot path
#                  cares about. Refuses rather than silently doing nothing if the
#                  cmdline carries no `subvol=` to replace, and reads the new
#                  cmdline back out of the signed UKI to confirm the change is
#                  in the thing that will actually be booted.
#
# Prerequisites, and they are not all obvious:
#   * the corrected module files must ALREADY be in the slot at
#     /usr/lib/dracut/modules.d/99shanios/ - the harness does not put the host's
#     working tree in here, and `/home/builduser/build` does not exist inside a
#     slot's namespace. Pass them in by content:
#         base64 -w0 <file> | ... | base64 -d > /usr/lib/dracut/modules.d/99shanios/<name>
#   * AND VERIFY THE COPY LANDED. An earlier attempt copied from a path that
#     does not exist inside a slot, the `cp` failed, and dracut cheerfully
#     regenerated the UKI from the OLD module - a run that looked successful and
#     tested nothing.
#   * the ESP must be mounted (the slot mounts it at /boot/efi)
set -uo pipefail
_regen_failed=0

break_root=0
expect=""
slots=()
for a in "$@"; do
  case "$a" in
    --break-root) break_root=1 ;;
    --expect-in-initrd=*) expect="${a#--expect-in-initrd=}" ;;
    -*) echo "regen-uki: unknown option $a" >&2; exit 2 ;;
    *)  slots+=("$a") ;;
  esac
done
[[ ${#slots[@]} -gt 0 ]] || slots=(green)

for SLOT in "${slots[@]}"; do
    M=/usr/lib/dracut/modules.d/99shanios
    ESP=/boot/efi
    UKI="$ESP/EFI/shanios/shanios-$SLOT.efi"
    KV=$(ls /usr/lib/modules/ 2>/dev/null | head -1)

    echo "=== $SLOT ==="
    [[ -n $KV ]] || { echo "  no kernel in /usr/lib/modules"; continue; }
    [[ -f $UKI ]] || { echo "  no UKI at $UKI"; continue; }
    [[ -d $M ]]   || { echo "  no dracut module dir at $M"; continue; }

    # Refuse to regenerate from a module the caller believes it just fixed but
    # which is not there. The failure this prevents is silent and looks like a
    # successful run.
    if grep -q 'instmods vfat' "$M/module-setup.sh" 2>/dev/null; then
        echo "  module: has instmods vfat"
    else
        echo "  WARNING: $M/module-setup.sh has no 'instmods vfat'. Regenerating"
        echo "           now would test the OLD module and report success."
    fi

    # objcopy -O binary cannot write to /dev/stdout: it exits 0 and produces
    # nothing, so the pipeline reads as an empty cmdline rather than an error.
    t=$(mktemp) || { echo "  mktemp failed"; continue; }
    if ! objcopy -O binary --only-section=.cmdline "$UKI" "$t" 2>/dev/null || [[ ! -s $t ]]; then
        echo "  could not read .cmdline from the existing UKI"; rm -f "$t"; continue
    fi
    CMD=$(tr -d '\0' < "$t"); rm -f "$t"
    [[ -n $CMD ]] || { echo "  empty cmdline - refusing"; continue; }
    echo "  cmdline: ${CMD:0:90}..."

    if (( break_root )); then
        # Refuse rather than silently regenerate a bootable UKI: a substitution
        # that does not apply produces a UKI that boots perfectly, which is the
        # exact shape of a run that reports success and tests nothing.
        if ! grep -q 'subvol=@' <<<"$CMD"; then
            echo "  --break-root: the cmdline has no 'subvol=@' to replace:"
            echo "      $CMD"
            echo "  Refusing - a UKI rebuilt from this would boot normally, so the"
            echo "  recovery path would never be reached. Nothing was changed."
            continue
        fi
        CMD=$(sed -E 's/subvol=@[^[:space:]]+/subvol=@no-such-slot/' <<<"$CMD")
        grep -q 'subvol=@no-such-slot' <<<"$CMD" || { echo "  --break-root: substitution did not apply"; continue; }
        echo "  --break-root: cmdline is now ${CMD:0:90}..."
        echo "  the root subvol does not exist, so this boot MUST fail to mount"
    fi

    before=$(stat -c %s "$UKI")
    # Keep the original until the rebuilt artifact has been VERIFIED below. It
    # used to be moved into place first and verified afterwards, so a rebuild
    # that produced the wrong cmdline left that UKI on the ESP with a FAIL line
    # printed above it and a zero exit status - an artifact in place and wrong,
    # which is what a power-cut boot through it would then measure.
    cp -f "$UKI" "${UKI}.shanios-regen.orig" 2>/dev/null || true
    if ! dracut --force --uefi --kver "$KV" --kernel-cmdline "$CMD" "${UKI}.tmp"; then
        echo "  dracut FAILED - the original UKI is untouched"; continue
    fi
    if ! sbsign --key /etc/secureboot/keys/MOK.key \
                --cert /etc/secureboot/keys/MOK.crt \
                "${UKI}.tmp" --output "${UKI}.tmp.signed"; then
        echo "  sbsign FAILED - the original UKI is untouched"; rm -f "${UKI}.tmp"; continue
    fi
    mv -f "${UKI}.tmp.signed" "$UKI"; rm -f "${UKI}.tmp"
    after=$(stat -c %s "$UKI")
    echo "  regenerated: ${before} -> ${after} bytes (delta $((after - before)))"

    # Read the cmdline back OUT OF THE SIGNED UKI. Everything above proves the
    # dracut call was given the right string; this proves the string is in the
    # artifact that will be booted. The gap between those two is where a silent
    # no-op lives, and it is the same shape as the copy that failed earlier and
    # regenerated a UKI from the old module while reporting success.
    t2=$(mktemp) || { echo "  mktemp failed"; continue; }
    if objcopy -O binary --only-section=.cmdline "$UKI" "$t2" 2>/dev/null && [[ -s $t2 ]]; then
        GOT=$(tr -d '\0' < "$t2")
        if (( break_root )); then
            if grep -q 'subvol=@no-such-slot' <<<"$GOT"; then
                echo "  VERIFIED: the signed UKI really carries subvol=@no-such-slot"
            else
                echo "  VERIFY FAILED: the signed UKI's cmdline is:"
                echo "      $GOT"
                echo "  It does not name the missing subvol, so this UKI would boot"
                echo "  normally and the recovery path would never be reached."
                _regen_verify_failed=1
            fi
        else
            if [[ "$GOT" == "$CMD" ]]; then
                echo "  VERIFIED: cmdline unchanged in the signed UKI"
            else
                echo "  VERIFY FAILED: signed UKI carries a different cmdline than the one given to dracut"
                echo "      expected: $CMD"
                echo "      got:      $GOT"
                _regen_verify_failed=1
            fi
        fi
    else
        echo "  could not read .cmdline back out of the signed UKI (not verified)"
        _regen_verify_failed=1
    fi
    # Only record the verdict HERE. Restoring the original has to wait until
    # after --expect-in-initrd has read the rebuilt UKI, or that check inspects
    # the artifact it is meant to be judging and reports about the wrong file.
    [[ -n ${_regen_verify_failed:-} ]] && _regen_failed=1
    rm -f "$t2"

    # Assert the caller's expected text really is inside the initramfs of the
    # artifact that will boot. Everything above proves what dracut was TOLD; this
    # proves what the UKI CONTAINS.
    if [[ -n $expect ]]; then
        found=no
        if objcopy -O binary --only-section=.initrd "$UKI" "$t2" 2>/dev/null && [[ -s $t2 ]]; then
            # The section does NOT begin with the initramfs. It opens with a cpio
            # stub (early_cpio/microcode); the real zstd stream starts at the first
            # zstd magic SOMEWHERE inside it. Assuming offset 0 - which the first
            # version of this did - finds a cpio stub, lists 7 entries, and reports
            # a module that is demonstrably present as missing. Same technique as
            # tests/check-uki-initrd.sh, for the same reason.
            # Two things this must get right, and both were wrong in the first
            # version - found by running it against a real UKI:
            #   1. the section does not BEGIN with the initramfs. It opens with a
            #      cpio stub (early_cpio/microcode); the zstd stream starts at the
            #      first zstd magic SOMEWHERE inside. Assuming offset 0 lists 7
            #      entries of stub.
            #   2. a module is installed into the initramfs as its HOOKS, under
            #      var/lib/dracut/hooks/<stage>/, not as modules.d/99shanios/.
            #      And `cpio -itv` prints NAMES, so grepping the listing can never
            #      find text - the files have to be extracted and searched.
            off=$(python3 -c "
import sys
d=open(sys.argv[1],'rb').read()
i=d.find(b'\x28\xb5\x2f\xfd')
print(i if i>=0 else -1)" "$t2" 2>/dev/null || echo -1)
            if [[ "$off" -ge 0 ]]; then
                python3 -c "
import sys
d=open(sys.argv[1],'rb').read()
open(sys.argv[2],'wb').write(d[int(sys.argv[3]):])" "$t2" "$t2.zst" "$off" 2>/dev/null
                if zstd -d -f -q "$t2.zst" -o "$t2.cpio" 2>/dev/null && [[ -s "$t2.cpio" ]]; then
                    mkdir -p "$t2.tree"
                    ( cd "$t2.tree" && cpio -id --quiet < "$t2.cpio" ) 2>/dev/null
                    if grep -rqF "$expect" "$t2.tree" 2>/dev/null; then
                        found=yes
                    fi
                fi
            fi
            rm -rf "$t2.zst" "$t2.cpio" "$t2.tree"
            fi
        if [[ $found == yes ]]; then
            echo "  VERIFIED: the initramfs really contains '$expect'"
        else
            echo "  VERIFY FAILED: '$expect' is NOT in this UKI's initramfs."
            echo "    The rebuild took its input from somewhere else - most often the"
            echo "    nspawn overlay, which \`enter\` boots and which can still hold an"
            echo "    older copy of the module than the slot's real subvolume."
            echo "    Check that before trusting anything this run reported."
        fi
        rm -f "$t2"
    fi
    echo "  NOTE: this is a test-only in-place rebuild; the image still carries the old module."

    # Everything that had to look at the rebuilt UKI has now looked. If its
    # cmdline did not verify, put the original back and stop: the artifact on
    # the ESP is not the one it claims to be, and a power-cut boot through it
    # would measure nothing while logging as though it had.
    if [[ -n ${_regen_verify_failed:-} ]]; then
        if [[ -f "${UKI}.shanios-regen.orig" ]]; then
            mv -f "${UKI}.shanios-regen.orig" "$UKI"
            echo "  RESTORED the original UKI - the rebuilt one did not verify, so it is not installed"
        fi
    fi
done

# A non-zero exit is the load-bearing half. The FAIL lines were already being
# printed; what was missing was anything a caller could test.
[[ -n ${_regen_failed:-} ]] && exit 1
exit 0